final class Glyph {                               // immutable intrinsic state
    final String code; final int w, h;
    private Glyph(String c, int w, int h) { this.code = c; this.w = w; this.h = h; }

    private static final ConcurrentHashMap<String, Glyph> POOL = new ConcurrentHashMap<>();
    static Glyph of(String code, int w, int h) {
        return POOL.computeIfAbsent(code, c -> new Glyph(c, w, h));
    }
}
// context: record Cell(Glyph glyph, int x, int y) {}
